INSERT INTO intelligence_models (kind, name, version, description, is_active, created_at) VALUES
('AUDIO_FEATURES', 'muse-analyzer', '1.0', 'First audio analysis pass supplied with the 2025 catalogue import.', 0, NOW() - INTERVAL 220 DAY),
('AUDIO_FEATURES', 'muse-analyzer', '2.1', 'Re-analysis with better tempo tracking and loudness normalisation.', 1, NOW() - INTERVAL 25 DAY),
