INSERT INTO world_archetypes (archetype_code, name, description, motif, palette, title_words, season_months) VALUES
('HEROIC', 'Heroic', 'Rising, brave and driving, like the last act of a hero''s story.', 'PEAKS', '["#F2A93B","#C2410C","#1E1B2E","#FDE68A"]', '{"lead":["Rising","Iron","Golden","Unbroken","Thunder"],"place":["Ascent","Horizon","Banner","Citadel","Run"]}', NULL),
('COSMIC', 'Cosmic', 'Weightless and vast, music for looking up.', 'ORBITS', '["#7C83FD","#0B1026","#C4B5FD","#38BDF8"]', '{"lead":["Orbit","Nebula","Stardust","Zero-G","Satellite"],"place":["Drift","Lullaby","Station","Tide","Garden"]}', NULL),
('NOIR', 'Noir', 'Dark streets, wet neon and heavy hearts.', 'GRID', '["#E11D48","#111827","#64748B","#F472B6"]', '{"lead":["Midnight","Neon","Concrete","Shadow","Static"],"place":["Alley","Pulse","Rain","Signal","District"]}', NULL),
('MYSTIC', 'Mysterious', 'Half-lit corridors and slow secrets.', 'STARS', '["#A78BFA","#1E1B4B","#5EEAD4","#E9D5FF"]', '{"lead":["Hidden","Moonlit","Silent","Veiled","Lantern"],"place":["Temple","Forest","Mirror","Corridor","Garden"]}', NULL),
('EPIC', 'Epic', 'Wide landscapes and big crescendos.', 'PEAKS', '["#3FB8AF","#0F2D2A","#F2A93B","#E2E8F0"]', '{"lead":["Endless","Thousand","Ancient","Wild","Storm"],"place":["Kingdoms","Plains","Voyage","Frontier","Saga"]}', NULL),
('ROMANCE', 'Romantic', 'Close voices, slow tempos, a little rain.', 'WAVES', '["#E86A92","#3B0A24","#FBCFE8","#F2A93B"]', '{"lead":["Velvet","Rose","Moonlight","Slow","First"],"place":["Letters","Promenade","Waltz","Balcony","Evenings"]}', NULL),
('WANDER', 'Adventurous', 'Open roads, ferries and new places.', 'SUNBURST', '["#F59E0B","#0E4D64","#FDE68A","#7DD3FC"]', '{"lead":["Open","Highway","Coastal","Wanderer''s","Sunlit"],"place":["Road","Postcards","Map","Ferry","Junction"]}', NULL),
('MEMORY', 'Nostalgic', 'Cassette warmth and old photographs.', 'RAIN', '["#C9A27E","#2A1F17","#F5E6D3","#8C6A4F"]', '{"lead":["Faded","Sepia","Old","Cassette","Summer"],"place":["Lane","Radio","Photographs","Afternoons","Matinee"]}', NULL),
('REBEL', 'Rebellious', 'Loud, restless and refusing to sit down.', 'EMBERS', '["#EF4444","#1C1917","#F97316","#FAFAF9"]', '{"lead":["Riot","Feral","Loud","Burning","Underground"],"place":["Anthem","Static","Engine","Uprising","Spark"]}', NULL),
('DREAMLIKE', 'Dreamlike', 'Soft focus, floating and half-awake.', 'WAVES', '["#9D8CFF","#1A1530","#BAE6FD","#FBCFE8"]', '{"lead":["Lucid","Cotton","Floating","Half-Awake","Velvet"],"place":["Cloud","Daydream","Shore","Echo","Haze"]}', NULL),
('DAWN', 'Dawn', 'First light, quiet courtyards and slow ragas.', 'SUNBURST', '["#F2A93B","#3B2A1A","#FDE68A","#7CC6B5"]', '{"lead":["First-Light","Saffron","Dewdrop","Early","Quiet"],"place":["Morning","Courtyard","Raga","Window","Path"]}', NULL),
('MONSOON', 'Monsoon', 'Grey skies, wet streets and songs for the window seat.', 'RAIN', '["#7CC6B5","#14262B","#A7C7E7","#F2A93B"]', '{"lead":["Monsoon","Petrichor","Rain-Soaked","Grey-Sky","Puddle"],"place":["Memories","Windows","Verandah","Ballads","Letters"]}', '6,7,8,9'),
('FESTIVE', 'Festive', 'Lamps, drums and courtyards full of people.', 'SUNBURST', '["#F59E0B","#3B0D0D","#FDE68A","#F472B6"]', '{"lead":["Lantern","Marigold","Firework","Thousand-Lamp","Drumroll"],"place":["Night","Procession","Courtyard","Celebration","Mela"]}', '10,11,1');
